export async function mountPanorama(stage,url,host){const T=await import('./vendor/three/three.module.js');const renderer=new T.WebGLRenderer({antialias:true});renderer.setPixelRatio(Math.min(devicePixelRatio||1,1.5));renderer.domElement.style.cssText='width:100%;height:100%;display:block;touch-action:none';stage.append(renderer.domElement);const scene=new T.Scene(),camera=new T.PerspectiveCamera(75,1,.1,100),geometry=new T.SphereGeometry(10,48,24);geometry.scale(-1,1,1);let texture;try{texture=await new T.TextureLoader().loadAsync(url);}catch(e){renderer.dispose();geometry.dispose();throw e;}if(!stage.isConnected||stage.closest('dialog')&&!stage.closest('dialog').open){texture.dispose();geometry.dispose();renderer.dispose();throw Error('Vista cerrada');}texture.colorSpace=T.SRGBColorSpace;const material=new T.MeshBasicMaterial({map:texture});scene.add(new T.Mesh(geometry,material));let yaw=-Math.PI/2,pitch=0,drag=null,dead=false;
 const draw=()=>{if(dead)return;const rect=stage.getBoundingClientRect();if(!rect.width||!rect.height)return;renderer.setSize(rect.width,rect.height,false);camera.aspect=rect.width/rect.height;camera.updateProjectionMatrix();const latitude=Math.max(-1.4,Math.min(1.4,pitch));camera.lookAt(Math.cos(latitude)*Math.sin(yaw),Math.sin(latitude),Math.cos(latitude)*Math.cos(yaw));renderer.render(scene,camera);};
 const down=e=>{drag={id:e.pointerId,x:e.clientX,y:e.clientY};renderer.domElement.setPointerCapture(e.pointerId);},move=e=>{if(!drag||drag.id!==e.pointerId)return;yaw-=(e.clientX-drag.x)*.005;pitch+=(e.clientY-drag.y)*.005;drag.x=e.clientX;drag.y=e.clientY;draw();},up=()=>drag=null,zoom=e=>{camera.fov=Math.max(35,Math.min(100,75/e.detail));draw();};renderer.domElement.addEventListener('pointerdown',down);renderer.domElement.addEventListener('pointermove',move);renderer.domElement.addEventListener('pointerup',up);renderer.domElement.addEventListener('pointercancel',up);const look=e=>{yaw+=e.detail;draw();};host.addEventListener('tour-look',look);host.addEventListener('tour-zoom',zoom);const size=new ResizeObserver(draw);size.observe(stage);const dialog=host.closest('dialog');const dispose=()=>{if(dead)return;dead=true;size.disconnect();mutation.disconnect();host.removeEventListener('tour-zoom',zoom);host.removeEventListener('tour-look',look);dialog?.removeEventListener('close',dispose);texture.dispose();geometry.dispose();material.dispose();renderer.dispose();renderer.domElement.remove();};const mutation=new MutationObserver(()=>{if(!host.isConnected||!stage.isConnected)dispose();});mutation.observe(document.body,{childList:true,subtree:true});dialog?.addEventListener('close',dispose,{once:true});draw();return dispose;}
